using System;
using System.IO;
using System.Collections.Generic;
using UnityEngine;
public static class RestaurantAnatomyReview {
 [Serializable] public class Run {public string label;public FlightState state;public RigidImpact[] contacts;public string[] broken;public int maxFragments,foodFragments,unexpectedDebrisPairs;public string[] foodModels;}
 [Serializable] public class Result {public string revision="crab-flight-anatomy1-exit1",scope="Original representative aquarium/restaurant segment, real Unity compound-body contacts and impulse-triggered breakage. Not mall/city/country/space completion; browser input and listening separate.";public List<Run> runs=new List<Run>();public bool noAutomaticBreak,reset,pause,repeat,weakStrong,comfort,spinMatters,retryButton;public int configurations;public bool foodIntegration,foodLODInvariant;public float foodDistanceDelta;public float repeatDistanceDelta,reducedRunDistanceDelta;public string comfortCriterion="same live body position/rotation/linear and angular velocity/mass unchanged by the toggle; separate chaotic runs also reported";}
 static Result result;static string dir;
 public static void RunAndWeb(){AnatomyEnvelopeReview.Generate();AnatomyModelReview.Run();Review();AnatomyExitReview.Run();Web();}
 public static void Web(){BuildFlight.Web("../delivery/UnityWeb/anatomy1-exit1-ready");File.Copy("../web-template/launch-input.js","../delivery/UnityWeb/anatomy1-exit1-ready/launch-input.js",true);}
 public static void Review(){

  dir=Path.GetFullPath("../evidence/anatomy-native02");Directory.CreateDirectory(dir);result=new Result();CrabFlightGame g=null;
  try{
   g=BuildFlight.PrepareScene();g.Initialize();g.Prepare("");Capture(g,"aquarium-ready");for(int i=0;i<600;i++)g.Tick(1f/60);result.noAutomaticBreak=g.State().glassBroken==0&&g.State().wallsBroken==0;
   var oldFood=Play(g,"baseline-cube-food",55,90,1,10.8f,true,false);var newFood=Play(g,"candidate-cc0-food",55,90,1,10.8f);result.foodIntegration=newFood.foodFragments==3&&newFood.foodModels.Length==3;result.foodDistanceDelta=newFood.state.distance-oldFood.state.distance;
   Play(g,"order-new-repeat",55,90,1,10.8f);Play(g,"order-old-repeat",55,90,1,10.8f,true,false);
   var weak=Play(g,"weak-low",10,10,1,1.2f);var strong=Play(g,"strong-low",10,85,1,10.2f);g.RetryLaunch("");result.retryButton=g.State().phase=="flight"&&g.State().glassBroken==0&&g.State().wallsBroken==0&&g.State().fragments==0;var button=Finish(g,"same-input-retry-button");result.retryButton=result.retryButton&&Mathf.Abs(strong.state.distance-button.state.distance)<.1f;var again=Play(g,"strong-repeat",10,85,1,10.2f);result.repeatDistanceDelta=Mathf.Abs(strong.state.distance-again.state.distance);result.repeat=result.repeatDistanceDelta<.1f&&strong.broken.Length==again.broken.Length;
   result.weakStrong=strong.state.glassBroken>0&&strong.state.wallsBroken>0&&strong.state.distance>weak.state.distance+3;
   var zero=Play(g,"same-power-no-spin",10,85,1,0);result.spinMatters=Mathf.Abs(zero.state.distance-strong.state.distance)>.1f||zero.broken.Length!=strong.broken.Length;
   Play(g,"left-low",10,85,-1,-10.2f);Play(g,"high-ceiling",55,90,1,10.8f);Play(g,"maximum-low",10,100,1,12);
   g.SetReducedMotion("1");var comfort=Play(g,"reduced-same-input",10,85,1,10.2f);result.reducedRunDistanceDelta=Mathf.Abs(comfort.state.distance-strong.state.distance);g.SetReducedMotion("0");
   Ready(g,10,85);g.BeginAim("");g.ReleaseLaunch(Input(10,85,1,10.2f));g.Tick(.2f);var before=g.State();var rotation=g.ReviewSimulation.Body.rotation;var body=g.ReviewSimulation.Body;var position=body.position;var linear=body.linearVelocity;var angular=body.angularVelocity;var mass=body.mass;g.SetReducedMotion("1");result.comfort=body.position==position&&Quaternion.Angle(body.rotation,rotation)<.00001f&&body.linearVelocity==linear&&body.angularVelocity==angular&&body.mass==mass;g.SetReducedMotion("0");g.SetPaused("1");for(int i=0;i<100;i++)g.Tick(1f/60);var after=g.State();result.pause=before.time==after.time&&before.destructionEvent==after.destructionEvent&&Quaternion.Angle(rotation,g.ReviewSimulation.Body.rotation)<.001f;g.SetPaused("0");
   g.Prepare("");result.reset=g.State().phase=="ready";g.BeginAim("");g.ReleaseLaunch(Input(10,85,1,10.2f));result.reset=result.reset&&g.State().glassBroken==0&&g.State().wallsBroken==0&&g.State().fragments==0;
   Finish(g,"reset-then-launch");
   foreach(float c in new[]{0f,50f,100f})foreach(float s in new[]{0f,50f,100f})foreach(float l in new[]{0f,50f,100f}){g.Prepare("");g.Configure(JsonUtility.ToJson(new FlightSettings{claw=c,shell=s,legs=l,angle=10,power=85}));Play(g,"parts-"+c+"-"+s+"-"+l,10,85,1,10.2f,false);result.configurations++;}
   Save();if(!result.foodIntegration||!result.foodLODInvariant||!result.noAutomaticBreak||!result.reset||!result.pause||!result.repeat||!result.weakStrong||!result.comfort||!result.spinMatters||!result.retryButton)throw new Exception("Restaurant comparison failed; inspect saved result");
  }catch(Exception e){Save();File.WriteAllText(Path.Combine(dir,"failure.txt"),e.GetType().Name+": "+e.Message);throw;}finally{if(g)g.ShutdownReviewPhysics();}
 }
 static void Save(){File.WriteAllText(Path.Combine(dir,"result.json"),JsonUtility.ToJson(result,true));}
 static void Ready(CrabFlightGame g,float angle,float power){g.SetPaused("0");g.Prepare("");g.Configure(JsonUtility.ToJson(new FlightSettings{claw=45,shell=45,legs=45,angle=angle,power=power}));}
 static string Input(float a,float p,int d,float s)=>JsonUtility.ToJson(new FlightAimInput{angle=a,power=p,direction=d,spinRps=s,spinPhase=0,eligible=true});
 static Run Play(CrabFlightGame g,string name,float a,float p,int d,float s,bool defaults=true,bool food=true){if(defaults)Ready(g,a,p);else g.Prepare("");g.ReviewSetFoodFragments(food);g.BeginAim("");g.ReleaseLaunch(Input(a,p,d,s));return Finish(g,name);}
 static Run Finish(CrabFlightGame g,string name){int glass=0,walls=0,max=0;bool foodCaptured=false,exitBefore=false,exitHit=false,exitAfter=false,exitFlight=false;float exitTime=-1;for(int i=0;i<9000&&!g.Finished;i++){g.Tick(1f/240);var state=g.State();if(name=="strong-low"){bool outsideWall=g.ReviewSimulation.BrokenObjects.Exists(x=>x.StartsWith("outer-wall"));if(!exitBefore&&state.worldX>19&&!outsideWall){Capture(g,"exit-before");exitBefore=true;}if(!exitHit&&outsideWall){Capture(g,"exit-impact");exitHit=true;exitTime=state.time;}if(exitHit&&!exitAfter&&state.time>=exitTime+.12f){Capture(g,"exit-after-120ms");exitAfter=true;}if(exitHit&&!exitFlight&&state.time>=exitTime+.6f&&state.worldX>29){Capture(g,"exit-outside-flight");exitFlight=true;}}max=Mathf.Max(max,state.fragments);if((name=="baseline-cube-food"||name=="candidate-cc0-food")&&!foodCaptured&&state.dishesBroken>0){Capture(g,name+"-contact");if(name=="candidate-cc0-food"){result.foodLODInvariant=FoodLODInvariant(g);CaptureFood(g,name+"-close");}foodCaptured=true;}if(name=="strong-low"&&state.glassBroken>glass){Capture(g,"glass-break");glass=state.glassBroken;}if(name=="strong-low"&&state.wallsBroken>walls){Capture(g,"first-wall-break");walls=state.wallsBroken;}}
  var run=new Run{label=name,state=g.State(),contacts=g.ReviewSimulation.Impacts.ToArray(),broken=g.ReviewSimulation.BrokenObjects.ToArray(),maxFragments=max,unexpectedDebrisPairs=g.ReviewSimulation.ReviewUnexpectedCrabDebrisContacts(),foodFragments=g.ReviewSimulation.FoodFragmentsSpawned,foodModels=g.ReviewSimulation.FoodFragmentModels.ToArray()};result.runs.Add(run);Save();if(name=="strong-low")Capture(g,"after-wall-result");
  if(!g.Finished||run.state.physicsFault.Length>0||max>32||run.unexpectedDebrisPairs>0)throw new Exception(name+" invalid: "+run.state.physicsFault+" fragments="+max);return run;
 }
 static bool FoodLODInvariant(CrabFlightGame g){bool valid=true;foreach(var o in g.ReviewSimulation.ReviewFragments){var lod=o.GetComponent<LODGroup>();if(!lod)continue;var b=o.GetComponent<Rigidbody>();var c=o.GetComponent<BoxCollider>();var p=b.position;var q=b.rotation;var v=b.linearVelocity;var a=b.angularVelocity;var center=c.center;var size=c.size;lod.ForceLOD(0);lod.ForceLOD(1);valid&=p==b.position&&Quaternion.Angle(q,b.rotation)<.000001f&&v==b.linearVelocity&&a==b.angularVelocity&&center==c.center&&size==c.size&&c.enabled;lod.ForceLOD(-1);}return valid;}
 static void CaptureFood(CrabFlightGame g,string name){var cam=g.ReviewCamera;var originals=g.ReviewSimulation.ReviewFragments;var food=Array.FindAll(originals,o=>o.GetComponent<LODGroup>()!=null);if(food.Length!=3)throw new Exception("Food physical fragments missing");var focus=food[0].transform.position;foreach(var o in food)focus+=o.transform.position;focus/=4;var p=cam.transform.position;var q=cam.transform.rotation;var size=cam.orthographicSize;var aspect=cam.aspect;cam.aspect=1.5f;cam.orthographicSize=4;cam.transform.position=focus+new Vector3(0,4,-10);cam.transform.LookAt(focus);var rt=RenderTexture.GetTemporary(900,600,24);var before=RenderTexture.active;cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var t=new Texture2D(900,600,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,900,600),0,0);t.Apply();File.WriteAllBytes(Path.Combine(dir,name+".png"),t.EncodeToPNG());cam.targetTexture=null;RenderTexture.active=before;RenderTexture.ReleaseTemporary(rt);UnityEngine.Object.DestroyImmediate(t);cam.transform.SetPositionAndRotation(p,q);cam.orthographicSize=size;cam.aspect=aspect;}
 static void Capture(CrabFlightGame g,string name){RigidFlightReview.Capture(g,Path.Combine(dir,name+".png"),844,390);}
}
